DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pm_b1_redact(jsonb,uuid,text)'::regprocedure) INTO d; d:=replace(d,'FUNCTION public.pm_b1_redact(','FUNCTION public.pm_b1_redact_proposed('); d:=replace(d,'IF NOT public.pm_project_b1_active() THEN RETURN _row; END IF;',''); EXECUTE d; END $$;
REVOKE ALL ON FUNCTION public.pm_b1_redact_proposed(jsonb,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_b1_redact_proposed(jsonb,uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pm_b1_review_redaction(_row jsonb,_project uuid,_user uuid,_kind text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Retired verification helper' USING ERRCODE='42501'; END $$;
CREATE FUNCTION public.pm_b1_preview_own(_project uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ DECLARE p jsonb; stages jsonb; BEGIN SELECT public.pm_b1_redact_proposed(to_jsonb(x),x.id,'project') INTO p FROM public.pm_projects x WHERE x.id=_project AND NOT x.finance_only; IF p IS NULL THEN RETURN NULL; END IF; SELECT coalesce(jsonb_agg(public.pm_b1_redact_proposed(to_jsonb(s),s.project_id,'stage') ORDER BY s.sort_order,s.id),'[]'::jsonb) INTO stages FROM public.pm_stages s WHERE s.project_id=_project; RETURN jsonb_build_object('project',p,'stages',stages,'areas',public.pm_project_viewer_areas(_project),'active',public.pm_project_b1_active()); END $$;
REVOKE ALL ON FUNCTION public.pm_b1_preview_own(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_b1_preview_own(uuid) TO authenticated,service_role;
COMMENT ON FUNCTION public.pm_b1_preview_own(uuid) IS 'Caller-only read-only future B1 projection for verification while production gate stays OFF; preserves source RLS and never changes identity or gate.';